create extension if not exists pgcrypto;
create table if not exists public.user_roles(user_id uuid primary key references auth.users(id) on delete cascade, role text not null check(role in ('super_admin','admin')) default 'admin');
create table if not exists public.access_keys(id uuid primary key default gen_random_uuid(),key_hash text unique not null,status text not null default 'active' check(status in ('active','revoked','expired')),created_at timestamptz not null default now(),expires_at timestamptz,is_lifetime boolean not null default false,device_limit int not null default 1 check(device_limit between 1 and 10),profile_group text not null default 'general',created_by uuid references auth.users(id),revoked_at timestamptz);
create table if not exists public.key_activations(id uuid primary key default gen_random_uuid(),access_key_id uuid not null references public.access_keys(id) on delete cascade,device_hash text not null,first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),unique(access_key_id,device_hash));
create table if not exists public.profiles(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',profile_group text not null default 'general',storage_path text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.key_profiles(access_key_id uuid references public.access_keys(id) on delete cascade,profile_id uuid references public.profiles(id) on delete cascade,primary key(access_key_id,profile_id));
create table if not exists public.site_settings(setting_key text primary key,setting_value jsonb not null default '{}'::jsonb,updated_at timestamptz not null default now(),updated_by uuid references auth.users(id));
create table if not exists public.audit_logs(id bigint generated always as identity primary key,actor_id uuid,action text not null,target_id text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table public.user_roles enable row level security;alter table public.access_keys enable row level security;alter table public.key_activations enable row level security;alter table public.profiles enable row level security;alter table public.key_profiles enable row level security;alter table public.site_settings enable row level security;alter table public.audit_logs enable row level security;
-- Intentionally no public table policies. Use role-checked Edge Functions.
